const input = $json.body ?? $json;
const maxLengths = { name: 100, email: 254, company: 200, role: 120, source: 100, message: 2000 };
const clean = {};
for (const [field, max] of Object.entries(maxLengths)) {
  const value = String(input[field] ?? '').trim();
  if (['name', 'email', 'company'].includes(field) && !value) throw new Error(`Missing lead field: ${field}`);
  if (value.length > max) throw new Error(`Lead field too long: ${field}`);
  clean[field] = value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
}
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(clean.email)) throw new Error('Invalid lead email');
const escapeHtml = value => value.replace(/[&<>\"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
const escapeSlack = value => value.replace(/[&<>]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[char]));
for (const field of ['name', 'company']) { clean[`${field}_html`] = escapeHtml(clean[field]); clean[`${field}_slack`] = escapeSlack(clean[field]); }
return [{ json: clean }];

let parsed;
try { parsed = JSON.parse($input.first().json.message.content); } catch { throw new Error('AI scorer returned invalid JSON'); }
const allowedSegments = ['hot', 'warm', 'cold'];
const score = Math.max(1, Math.min(10, Number(parsed.score)));
if (!Number.isFinite(score) || !allowedSegments.includes(parsed.segment)) throw new Error('AI scorer returned an invalid decision');
const safeText = (value, max) => String(value ?? '').trim().slice(0, max);
const escapeHtml = value => value.replace(/[&<>\"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
const escapeSlack = value => value.replace(/[&<>]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[char]));
const reasoning = safeText(parsed.reasoning, 500);
const suggestedAction = safeText(parsed.suggested_action, 500);
const lead = $('Validate Lead Input').first().json;
return [{ json: { ...lead, ai_score: score, segment: parsed.segment, reasoning: escapeSlack(reasoning), suggested_action: suggestedAction, suggested_action_slack: escapeSlack(suggestedAction), suggested_action_html: escapeHtml(suggestedAction), scored_at: new Date().toISOString() } }];
